const swap = depth > width, a = swap ? depth : width, b = swap ? width : depth, o = overhang;
const s = Math.tan(radians(pitch)), tc = thickness / Math.cos(radians(pitch));
const A = a / 2 + o, B = b / 2 + o, ye = -o * s, yt = b / 2 * s + tc, rl = Math.max(0, a / 2 - b / 2);
const P = (x, y, z) => addpoint(0, swap ? [z, y, x] : [x, y, z]);
const b0 = P(-A, ye, -B), b1 = P(A, ye, -B), b2 = P(A, ye, B), b3 = P(-A, ye, B);
const e0 = P(-A, ye + tc, -B), e1 = P(A, ye + tc, -B), e2 = P(A, ye + tc, B), e3 = P(-A, ye + tc, B);
const r0 = P(-rl, yt, 0), r1 = rl > 1e-6 ? P(rl, yt, 0) : r0;
const face = (pts, grp) => { const u = pts.filter((p, i) => pts.indexOf(p) === i); const pr = addprim(0, 'poly', swap ? u.slice().reverse() : u); setprimgroup(0, grp, pr, 1); };
face([b0, b1, b2, b3], 'fascia');
